package com.amit.jobagent.application;
import com.amit.jobagent.common.persistence.MutableEntity;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="application_package")class ApplicationPackage extends MutableEntity{
 @Column(name="candidate_id",nullable=false,updatable=false)UUID candidateId;@Column(name="job_posting_id",nullable=false,updatable=false)UUID jobId;@Column(name="current_revision_id")UUID currentRevisionId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)ApplicationPackageStatus status;@Column(name="created_by",nullable=false,updatable=false,length=150)String createdBy;@Column(name="stale_reason",length=120)String staleReason;
 protected ApplicationPackage(){}ApplicationPackage(UUID candidate,UUID job,String actor){candidateId=candidate;jobId=job;createdBy=actor;status=ApplicationPackageStatus.REQUESTED;}void generating(){if(status==ApplicationPackageStatus.ARCHIVED)throw new com.amit.jobagent.common.error.ConflictException("Archived packages cannot be regenerated");status=ApplicationPackageStatus.GENERATING;}void ready(UUID revision){currentRevisionId=revision;status=ApplicationPackageStatus.READY;staleReason=null;}void restore(UUID revision,ApplicationPackageStatus restoredStatus,String restoredReason){currentRevisionId=revision;status=restoredStatus;staleReason=restoredReason;}void fail(){status=ApplicationPackageStatus.FAILED;}void archive(){status=ApplicationPackageStatus.ARCHIVED;}void stale(String reason){if(status!=ApplicationPackageStatus.ARCHIVED){status=ApplicationPackageStatus.STALE;staleReason=reason;}}
}
